<script lang="ts">
import type {Catalog} from './locales';import Toggle from './components/Toggle.svelte';import JobLog from './components/JobLog.svelte';
let {t,request,can,onChanged}=$props<{t:Catalog;request:(url:string,body?:object)=>Promise<any>;can:(permission:string)=>boolean;onChanged:()=>void}>();
let dialog:HTMLDialogElement,confirmDialog:HTMLDialogElement;let name=$state(''),tags=$state(''),disabled=$state(false),busy=$state(false),error=$state(''),jobId=$state(''),deleting=$state(false),sources=$state(false),backups=$state(false),data=$state(false),info=$state<any>(null);
export function open(bundle:string,meta?:{tags:string[];autostartDisabled:boolean}){name=bundle;tags=meta?.tags.join(', ')??'';disabled=meta?.autostartDisabled??false;error='';jobId='';deleting=false;sources=false;backups=false;data=false;info=null;dialog.showModal();}
async function save(kind:string){busy=true;error='';try{await request('/api/bundles/'+kind,{name,...(kind==='tags'?{tags:tags.split(',').map(s=>s.trim()).filter(Boolean)}:{autostartDisabled:disabled})});onChanged();}catch(e){error=(e as Error).message;}finally{busy=false;}}
async function deleteInfo(){busy=true;try{info=await request('/api/bundles/delete-info',{name});deleting=true;}catch(e){error=(e as Error).message;}finally{busy=false;}}
async function remove(){if(!can('bundles.stop'))return;confirmDialog.close();busy=true;error='';try{const r=await request('/api/bundles/delete',{name,sources,backups,data});jobId=r.id;}catch(e){error=(e as Error).message;busy=false;}}
</script>
<dialog bind:this={dialog} class="project-dialog" aria-labelledby="bundle-manage-title"><header class="dialog-heading"><h2 id="bundle-manage-title">{t.bundleManage} · {name}</h2><button onclick={()=>dialog.close()}>{t.bxClose}</button></header>
{#if jobId}<JobLog {t} {request} {jobId} ondone={()=>{busy=false;onChanged();}}/>{:else}<div class="project-form-grid"><section><h3>{t.bundleCategories}</h3><label>{t.bundleCategories}<input bind:value={tags} disabled={busy||!can('bundles.tags')} maxlength="820"/></label><p class="muted">{t.bundleTagHint}</p><button disabled={busy||!can('bundles.tags')} onclick={()=>save('tags')}>{t.btSave}</button></section>
<section><Toggle checked={disabled} label={t.bundleAutostartOff} disabled={busy||!can('bundles.autostart')} onchange={v=>disabled=v}/><p class="muted">{t.bundleAutostartHint}</p><button disabled={busy||!can('bundles.autostart')} onclick={()=>save('autostart')}>{t.btSave}</button></section></div>
{#if can('bundles.delete')}<section class="bundle-delete-section"><h3>{t.bundleDelete}</h3>{#if !deleting}<button class="danger" disabled={busy||!can('bundles.stop')} onclick={deleteInfo}>{t.bundleDelete}</button>{:else}<p>{t.bundleDeleteHint}</p><p><strong>{t.bundleDeleteFiles}</strong></p><Toggle checked={sources} label={t.bundleDeleteSource} disabled={busy||!info.hasSource||!can('bundles.sources.delete')} onchange={v=>sources=v}/><Toggle checked={backups} label={t.bundleDeleteBackups} disabled={busy||!info.hasBackups} onchange={v=>backups=v}/><Toggle checked={data} label={t.bundleDeleteData} disabled={busy||!info.dataAvailable||!can('bundles.data.delete')} onchange={v=>data=v}/><p class="muted">{t.bundleDataUnavailable}</p><button class="danger" disabled={busy||!can('bundles.stop')} onclick={()=>confirmDialog.showModal()}>{t.bundleDelete}</button>{/if}</section>{/if}{/if}
{#if error}<p class="error" role="alert">{t.errors[error as keyof typeof t.errors]??t.errors['request.failed']}</p>{/if}</dialog>
<dialog bind:this={confirmDialog}><h2>{t.bundleDelete}</h2><p>{t.bundleDeleteConfirm.replace('{name}',name)}</p><div class="actions"><button onclick={()=>confirmDialog.close()}>{t.cancel}</button><button class="danger" disabled={busy||!can('bundles.stop')} onclick={remove}>{t.bundleDelete}</button></div></dialog>
